{"file_path":"src/parse.js","content":"/**
 * Parses the line-oriented election format described in the task: a
 * `candidates` declaration followed by any number of `ballot` records.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

function fail(message, line) {
  throw new ParseError(message, line)
}

export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const candidateSet = new Set()
  const candidates = []
  let candidatesSeen = false
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidatesSeen) {
        fail('candidates must be declared once, before any ballot', lineNo)
      }
      const rest = words.slice(1)
      if (rest.length === 0) {
        fail('expected candidates <name>...', lineNo)
      }
      for (const name of rest) {
        if (!NAME_RE.test(name)) {
          fail(`invalid candidate name ${name}`, lineNo)
        }
        if (candidateSet.has(name)) {
          fail(`candidate ${name} is declared twice`, lineNo)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
      candidatesSeen = true
    } else if (directive === 'ballot') {
      if (!candidatesSeen) {
        fail('candidates must be declared once, before any ballot', lineNo)
      }
      const rest = words.slice(1)
      if (rest.length < 2) {
        fail('expected ballot <count> <candidate>...', lineNo)
      }
      const countStr = rest[0]
      const names = rest.slice(1)
      if (!COUNT_RE.test(countStr)) {
        fail('count must be a positive integer', lineNo)
      }
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          fail(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
      }
      ballots.push({ count: parseInt(countStr, 10), names })
    } else {
      fail(`unknown directive ${directive}`, lineNo)
    }
  }

  if (!candidatesSeen) {
    fail('no candidates', null)
  }

  return { candidates, ballots }
}

export { ParseError }
"}

