{"file_path":"src/election.js","content":"/**
 * Runs the instant-runoff count described in the task, given the parsed
 * candidate list and ballots, producing a per-round trace and the winner.
 */

function tieBreak(tied, history) {
  let candidates = tied.slice()
  while (candidates.length > 1) {
    let separated = false
    for (const roundVotes of history) {
      const vals = candidates.map((c) => roundVotes.get(c))
      const uniq = new Set(vals)
      if (uniq.size > 1) {
        const min = Math.min(...vals)
        candidates = candidates.filter((c) => roundVotes.get(c) === min)
        separated = true
        break
      }
    }
    if (!separated) break
  }
  if (candidates.length === 1) return candidates[0]
  return candidates.reduce((a, b) => (a > b ? a : b))
}

export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const c of continuing) votes.set(c, 0)
    let exhausted = 0
    for (const ballot of ballots) {
      let picked = null
      for (const name of ballot.names) {
        if (continuing.has(name)) {
          picked = name
          break
        }
      }
      if (picked !== null) {
        votes.set(picked, votes.get(picked) + ballot.count)
      } else {
        exhausted += ballot.count
      }
    }
    history.push(votes)

    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)
    let eliminated = null
    let roundWinner = null
    let noWinner = false

    if (activeTotal === 0) {
      noWinner = true
    } else {
      for (const [name, v] of votes) {
        if (v * 2 > activeTotal) {
          roundWinner = name
          break
        }
      }
      if (!roundWinner) {
        const minVotes = Math.min(...votes.values())
        const tied = [...votes.keys()].filter((k) => votes.get(k) === minVotes)
        eliminated = tied.length === 1 ? tied[0] : tieBreak(tied, history)
        continuing.delete(eliminated)
      }
    }

    rounds.push({ votes, exhausted, eliminated })

    if (roundWinner) {
      winner = roundWinner
      break
    }
    if (noWinner) {
      winner = null
      break
    }
    if (continuing.size === 0) {
      winner = null
      break
    }
  }

  return { rounds, winner }
}
"}

