 * Formats the per-round trace produced by runElection into the textual
 * output required by the `rounds` and `tally` modes.
 */

export function formatRoundsLine(roundNumber, votes, exhausted) {
  const entries = [...votes.entries()]
  entries.sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, count]) => `${name}=${count}`)
  parts.push(`exhausted=${exhausted}`)
  return `round ${roundNumber}: ${parts.join(' ')}`
}

export function formatRounds(result) {
  const lines = []
  result.rounds.forEach((round, i) => {
    lines.push(formatRoundsLine(i + 1, round.votes, round.exhausted))
    if (round.eliminated) {
      lines.push(`eliminated ${round.eliminated}`)
    }
  })
  lines.push(result.winner ? `winner ${result.winner}` : 'no winner')
  return lines.join('\n') + '\n'
}

export function formatTally(result) {
  const lines = []
  lines.push(`rounds ${result.rounds.length}`)
  lines.push(result.winner ? `winner ${result.winner}` : 'no winner')
  return lines.join('\n') + '\n'
}
"}

