/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { runElection } from './election.js'
import { formatRounds, formatTally } from './format.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require_fs()
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function require_fs() {
  // deferred require to keep ESM top clean
  return globalThis.__fs || (globalThis.__fs = requireModule())
}

function requireModule() {
  const { createRequire } = require('node:module')
  return createRequire(import.meta.url)('node:fs')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      const prefix = err.line === null ? 'error: ' : `error: line ${err.line}: `
      process.stderr.write(`${prefix}${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const result = runElection(election.candidates, election.ballots)
  const output = mode === 'rounds' ? formatRounds(result) : formatTally(result)
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

